// Minimal reimplementation of the subset of Python's argparse behavior
// used by this program: required long options, -h/--help, byte-exact
// usage/help/error output, and exit codes 0 (help) / 2 (errors).

import path from 'node:path';

export class ArgumentParser {
  constructor(options = {}) {
    this.prog = options.prog !== undefined
      ? options.prog
      : path.basename(process.argv[1]);
    // Added arguments, in order of addition: { name, dest, metavar, required }
    this.arguments = [];
  }

  addArgument(name, options = {}) {
    const { required = false } = options;
    const dest = name.replace(/^--/, '');
    this.arguments.push({
      name,
      dest,
      metavar: dest.toUpperCase(),
      required: Boolean(required),
    });
  }

  _usageLine() {
    let line = `usage: ${this.prog} [-h]`;
    for (const arg of this.arguments) {
      line += ` --${arg.dest} ${arg.metavar}`;
    }
    return line;
  }

  _helpText() {
    const lines = [this._usageLine(), '', 'options:'];
    lines.push('  -h, --help  show this help message and exit');
    for (const arg of this.arguments) {
      lines.push(`  --${arg.dest} ${arg.metavar}`);
    }
    return lines.join('\n') + '\n';
  }

  _printHelpAndExit() {
    process.stdout.write(this._helpText());
    process.exit(0);
  }

  _errorAndExit(message) {
    process.stderr.write(`${this._usageLine()}\n${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  parseArgs(argv = process.argv.slice(2)) {
    const byName = new Map(this.arguments.map((arg) => [arg.name, arg]));
    const values = {};
    const extras = [];

    let i = 0;
    while (i < argv.length) {
      const token = argv[i];

      if (token === '-h' || token === '--help') {
        this._printHelpAndExit();
      }

      if (token.startsWith('--') && token.includes('=')) {
        const eq = token.indexOf('=');
        const name = token.slice(0, eq);
        const value = token.slice(eq + 1);
        const arg = byName.get(name);
        if (arg) {
          values[arg.dest] = value;
        } else {
          extras.push(token);
        }
        i += 1;
        continue;
      }

      if (token.startsWith('--')) {
        const arg = byName.get(token);
        if (arg) {
          const next = argv[i + 1];
          if (next === undefined || (next.startsWith('-') && next !== '-')) {
            this._errorAndExit(`argument ${arg.name}: expected one argument`);
          }
          values[arg.dest] = next;
          i += 2;
          continue;
        }
        extras.push(token);
        i += 1;
        continue;
      }

      // Unknown short option or bare positional.
      extras.push(token);
      i += 1;
    }

    const missing = this.arguments
      .filter((arg) => arg.required && !(arg.dest in values))
      .map((arg) => arg.name);
    if (missing.length > 0) {
      this._errorAndExit(
        `the following arguments are required: ${missing.join(', ')}`,
      );
    }

    if (extras.length > 0) {
      this._errorAndExit(`unrecognized arguments: ${extras.join(' ')}`);
    }

    return values;
  }
}

