cd /output && node --input-type=module -e "
import { ArgumentParser } from './lib/argparse.mjs';
process.argv[1] = '/some/dir/test11.mjs';
const p = new ArgumentParser();
p.addArgument('--a', { required: true });
p.addArgument('--b', { required: true });
p.addArgument('--c', { required: true });
console.log(JSON.stringify(p.parseArgs(['--a', 'x', '--b=y', '--c', '-'])));
"

